import{_ as o,l,o as e,c as i,v as r,p as d,x as n,d as h,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"凸包 Graham / Andrew","description":"","frontmatter":{"title":"凸包 Graham / Andrew","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/convex-hull.md","filePath":"cs/convex-hull.md","lastUpdated":1789023840000}'),p={name:"cs/convex-hull.md"};function m(_,a,A,u,f,E){const t=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="凸包-graham-andrew" tabindex="-1">凸包 Graham / Andrew <a class="header-anchor" href="#凸包-graham-andrew" aria-label="Permalink to &quot;凸包 Graham / Andrew&quot;">​</a></h1><div class="epigraph"><p>平面点集的凸包是包含所有点的最小凸多边形；排序后单调栈判左转，Graham $O(n\\log n)$，Andrew 上下链同阶。</p><footer>—— 据 Graham, An Efficient Algorithm for Determining the Convex Hull of a Finite Planar Set, 1972；Andrew, 1979；CLRS 第 33 章整理</footer></div><p>上一课<a href="/cs/regex-backtracking">正则匹配</a>收束串。平面几何从凸包起。缺口是凸包算法：叉积定向、共线。不重写排序下界。后课旋转卡壳在凸包上转。本课只静态点集。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>凸包顶点按逆时针。Graham：最低点（再最左）为极点，极角排序，栈上保持左转。Andrew：按 \\(x\\) 排序，做下凸链与上凸链，共线策略统一。二者排序 \\(O(n\\log n)\\) 主导。Jarvis 礼品包装 \\(O(nh)\\)，\\(h\\) 为包上点数。</p><p>缺口是栈与叉积，不是半平面交（后课）。</p><h3 id="极角排序要稳定共线" tabindex="-1">极角排序要稳定共线 <a class="header-anchor" href="#极角排序要稳定共线" aria-label="Permalink to &quot;极角排序要稳定共线&quot;">​</a></h3><p>叉积为零时按距离。Andrew 少用 <code>atan2</code>，数值更好。不要无排序声称 \\(O(n)\\)——需要额外假设（整数网格三点不共线等）或更重理论。</p><p><span class="marginnote">Graham 1972。Andrew monotone chain 1979。CLRS 33.3。后课旋转卡壳、直径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>去重点。Andrew：排序，正反各扫一次栈。输出去掉重复端点。</p>',11)),(e(),d(c,null,{default:n(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E7%82%B9%E9%9B%86%22%5D%20--%3E%20SORT%5B%22%E6%9E%81%E8%A7%92%E6%88%96%20x%20%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SORT%20--%3E%20ST%5B%22%E6%A0%88%E4%BF%9D%E6%8C%81%E5%B7%A6%E8%BD%AC%22%5D%0A%20%20ST%20--%3E%20HULL%5B%22%E5%87%B8%E5%8C%85%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>下包络是凸包的一半。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>左转 = 叉积 \\(\\gt 0\\)（约定）。凹处弹出。排序后相邻才可能是边。与 CHT：CHT 是对偶直线，本课是点。与 MST：凸包不是生成树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维凸包。动态凸包点名。后课默认：平面凸包 \\(O(n\\log n)\\) Graham/Andrew。下一课旋转卡壳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>排序 + 单调栈左转。</li><li>Andrew 上下链少极角。</li><li>主导项是排序 \\(O(n\\log n)\\)。</li><li>出处：Graham, 1972；Andrew, 1979；CLRS 第 33 章。</li></ul>',7))])}const S=o(p,[["render",m]]);export{x as __pageData,S as default};
